head.script:
scwin.onpageload = function () {

};

// 발행사코드 전역 변수
scwin.isurCdValue = "";

/**
 * @method
 * @name comIsurCode
 * @description searchIsurCode 구 명칭 호환 별칭
 * @deprecated scwin.searchIsurCode 사용
 * @param {Object} codeComp 발행사코드 autoComplete 컴포넌트
 * @param {Object} labelComp 발행사명 표시 컴포넌트
 * @returns {Promise} 조회·바인딩 완료 Promise
 * @hidden N
 * @exception
 * @example scwin.searchIsurCode(acb_isurCd, ibx_isurCdNm);
 */
scwin.comIsurCode = function (codeComp, labelComp) {
	return scwin.searchIsurCode(codeComp, labelComp);
};

/**
 * @method
 * @name searchIsurCode
 * @description 발행사코드 autoComplete 검색 공통함수. 발행사 목록을 조회해 autoComplete 그리드로 구성하고 코드·명 연동 이벤트를 바인딩한다. filter 생략 시 세션 정보(js_bond_yn·js_market) 기반으로 조회 조건을 분기한다.
 * @param {Object} codeComp 발행사코드 autoComplete 컴포넌트
 * @param {Object} labelComp 발행사명 표시 컴포넌트
 * @param {Object} [filter] 조회 필터(생략 시 세션 기반 분기)
 * @param {String} [filter.mktTpCd] 시장구분코드(예: "Y" 선물옵션 대상자산)
 * @param {String} [filter.listStatCd] 상장구분코드(예: "Y" 상장법인)
 * @returns {Promise} 조회·바인딩 완료 Promise
 * @hidden N
 * @exception
 * @example
 * scwin.searchIsurCode(acb_isurCd, ibx_isurCdNm);
 * scwin.searchIsurCode(acb_isurCd, ibx_isurCdNm, { mktTpCd: "Y", listStatCd: "" });
 */
scwin.searchIsurCode = async function (codeComp, labelComp, filter) {
	scwin.js_com_Isurcd = codeComp;		// 발행사코드
	scwin.js_com_Isurnm = labelComp;	// 발행사명

	// LIST_STAT_CD=
	// SPOT_ISU_TRD_MKT_TP_CD="+scwin.js_com_market    
	if (codeComp._wTagName !== "autoComplete") return;

	let url;
	let comAbbrv = labelComp.getValue();
    const mktTpCd = $c.session.getUserInfo("market") || "";

	// 2009.12.07(횝사팝업창에서 'js_bond_yn' 가 선언되어 있지 않을시 스크립트 오류발생. 인클루드 되어있지않을시 'N'으로 셋팅 P.H.J)
	// try{
	//     $c.session.getUserInfo("js_bond_yn") = $c.session.getUserInfo("js_bond_yn");
	// }catch(E){
	//     $c.session.getUserInfo("js_bond_yn") = "N";
	// }

	if (filter) {
		url = "/api/discls/common/popup/select-list-isur-cd-value?mktTpCd=" + (filter.mktTpCd || "") + "&listStatCd=" + (filter.listStatCd || "") + "&comAbbrv=" + comAbbrv;
	} else if ($c.session.getUserInfo("bondYn") === "Y") {
		// 2009.09.01 채권공시관련 추가
		url = "/api/discls/common/popup/select-list-isur-cd-value?listStatCd=Y&comAbbrv=" + comAbbrv;
	} else {
		url = "/api/discls/common/popup/select-list-isur-cd-value?mktTpCd=" + mktTpCd + "&listStatCd=&comAbbrv=" + comAbbrv;
	}

	const dcOptions = {
		baseNode: "list",
		repeatNode: "map",
		saveRemovedData: "true"
	};

	let dltObj = $c.data.createDataList(`dlt_isurCd_${codeComp.getID()}`, ["isurCd", "comNm", "comAbbrv", "comEngAbbrv", "listStatCd", "spotIsuTrdMktTpCd", "oldComAbbrv"], ["text", "text", "text", "text", "text", "text", "text"], dcOptions);
	let gridObj = {
		"nodeset": "data:" + dltObj.getID(), "value": "isurCd", "label": "comAbbrv", 
		"item": [
			{ "ref": "spotIsuTrdMktTpCd", "header": "시장구분", "style": "width:90px;height:25px", "headerStyle": "height:28px", "hidden": "false", "sortable": "false" },
			{ "ref": "listStatCd", "header": "상장구분코드", "style": "width:90px;height:25px", "headerStyle": "height:28px", "hidden": "true", "sortable": "false" }, // "headerStyle": "height:0px;display:none"
			{ "ref": "comAbbrv", "header": "회사명", "style": "width:310px;text-align:left", "headerStyle": "", "sortable": "false" },
			{ "ref": "isurCd", "header": "발행기관코드", "style": "width:115px", "headerStyle": "", "sortable": "false", "showSortableImage": "false" },
			{ "ref": "oldComAbbrv", "header": "oldComAbbrv", "style": "width:150px", "headerStyle": "", "hidden": "true", "sortable": "false" }
		]
		, "id": "grdIsurCd", "width": "510", "label": "comAbbrv", "autoFit": "none", "value": "isurCd", "visibleRowNum": "10", "sortable": "false", "showSortableImage": "false"
	};

	codeComp.setGridItemset(gridObj);

	// 회사코드 취득
	const isurCodeOption = {
		id: "sbm_isurCode",
		action: url,
		method: "get",
		isProcessMsg: false
	};

	let res = await $c.sbm.executeDynamic(isurCodeOption, {});
	if (res.responseJSON.success === true) {
		dltObj.setJSON(res.responseJSON.body);
	}

	WebSquare.getBody().getLayerListener().show(codeComp.getID(), {});
	WebSquare.getBody().getLayerListener().hide(codeComp.getID(), {});

	const gridView = scwin.js_com_Isurcd?.itemTable.gridView;

	// gridView.options.showSortableImage = false;

	gridView?.setSortable(gridView.getHeaderColID(0), false);
	gridView?.setSortable(gridView.getHeaderColID(1), false);
	gridView?.setSortable(gridView.getHeaderColID(2), false);
	gridView?.setSortable(gridView.getHeaderColID(3), false);
	gridView?.setSortable(gridView.getHeaderColID(4), false);

	// gridView?.setHeaderSortImage(gridView.getHeaderColID(0), 0, 0);
	// gridView?.setHeaderSortImage(gridView.getHeaderColID(1), 0, 0);
	// gridView?.setHeaderSortImage(gridView.getHeaderColID(2), 0, 0);
	// gridView?.setHeaderSortImage(gridView.getHeaderColID(3), 0, 0);
	// gridView?.setHeaderSortImage(gridView.getHeaderColID(4), 0, 0);

	// customFormatter 설정
	gridView.setCustomFormatter("spotIsuTrdMktTpCd", scwin.__setSpotIsuTrdMktTpCdFormatter);

	// label 설정 이벤트
	codeComp.unbind("onviewchange");
	codeComp.bind("onviewchange", function (info) {
		// console.log("onviewchange info === ", info);
		let comAbbrv = this.getScopeWindow().$p.getComponentById(dltObj.getID()).getCellData(info.newSelectedIndex, "comAbbrv");
		if (info.newValue === "" || info.newSelectedIndex === -1) comAbbrv = "";
		labelComp.setValue(comAbbrv);

		scwin.isurCdValue = info.newValue;
	}); 

	// label 설정 이벤트
	codeComp.unbind("oneditend");
	codeComp.bind("oneditend", function (value) {
		// console.log("oneditend value === ", value, scwin.isurCdValue);
		if ($c.util.isEmpty(value) || (scwin.isurCdValue !== "" && value !== scwin.isurCdValue)) {
			comAbbrv = "";
			labelComp.setValue(comAbbrv);
		}

		scwin.isurCdValue = value;
	});

	// label 설정 이벤트
	codeComp.unbind("oneditenter");
	codeComp.bind("oneditenter", function () {
		// console.log("oneditenter === ");
		const gridView = scwin.js_com_Isurcd?.itemTable.gridView;
		const isurCd = gridView.getCellData(0, "isurCd");

		if (gridView?.getRowCount() === 1 && codeComp.dom.input.value === isurCd) {
			labelComp.setValue(gridView.getCellData(0, "comAbbrv"));
			scwin.isurCdValue = gridView.getCellData(0, "isurCd");
		}
	});

	// emptyItem=true인 경우 keepValue 속성이 설정되지 않아 강제 설정
	codeComp.noResult = "keepValue";
	codeComp.options.noResult = "keepValue";

	// 코드 초기화
	codeComp.setValue("");
	codeComp.selectedIndex = -1;
    codeComp.dom.label.textContent = "";
    codeComp.dom.input.value = "";
};

/**
 * @method
 * @name isurcdSearchBond
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.isurcdSearchBond = function (grdObj, grdObj2) {
	scwin.js_com_Isurcd = grdObj;// 발행사코드
	scwin.js_com_Isurnm = grdObj2;// 발행사명

	// 팝업 오픈
	const url = "/ui/common/ULDCOM00007_BOND.xml";
	const param = {};

	const options = {
        id: "virWinSave",
        popupName: "채권법인검색창",
        frameModal: "top",
		width: 618,
		height: 730
    };

	$c.win.openPopup(url, options, param);		
};

/**
 * @method
 * @name isurcdSearch
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.isurcdSearch = function (grdObj, grdObj2) {
	scwin.js_com_Isurcd = grdObj;// 발행사코드
	scwin.js_com_Isurnm = grdObj2;// 발행사명 

	const opts = {
		id: "ULDCOM00007",
		popupName: "발행회사검색창",
		width: 618,
		height: 730,
		frameModal: "top"
	};

	$c.win.openPopup("/ui/common/ULDCOM00007.xml", opts);
};
